SELECT "Generico_5"."Anunciante" AS "Anunciante",   "Generico_5"."Anunciante" AS "Datos__copia_",   SUM("Generico_5"."InversionUS") AS "TEMP_TC___2622528870__0_",   SUM("Generico_5"."InversionUS") AS "sum_Calculation_0061002123102817_ok",   CAST(EXTRACT(YEAR FROM "Generico_5"."FECHA") AS BIGINT) AS "yr_FECHA_ok" FROM "Generico_5" WHERE (("Generico_5"."Anunciante" IN ('BANTRAB/TODOTICKET', 'TODOTICKET', 'TODOTICKET.COM')) AND (CAST(EXTRACT(YEAR FROM "Generico_5"."FECHA") AS BIGINT) >= 2010) AND (CAST(EXTRACT(YEAR FROM "Generico_5"."FECHA") AS BIGINT) <= 2015)) GROUP BY "Generico_5"."Anunciante",   "yr_FECHA_ok",   "Generico_5"."Anunciante";
